    11  static void
    12  ofctl_parse_flows__(struct ofputil_flow_mod *fms, size_t n_fms,
    13                      enum ofputil_protocol usable_protocols)
    14  {
    15      enum ofputil_protocol protocol = 0;
    16      char *usable_s;
    17      size_t i;
    18
    19      usable_s = ofputil_protocols_to_string(usable_protocols);
    20      printf("usable protocols: %s\n", usable_s);
    21      free(usable_s);
    22
    23      if (!(usable_protocols & OFPUTIL_P_ANY)) {
    24          printf("no usable protocol\n");
    25      }
    26      for (i = 0; i < sizeof(enum ofputil_protocol) * CHAR_BIT; i++) {
    27          protocol = 1 << i;
    28          if (protocol & usable_protocols & OFPUTIL_P_ANY) {
    29              break;
    30          }
    31      }
    32      ovs_assert(is_pow2(protocol));
    33
    34      printf("chosen protocol: %s\n", ofputil_protocol_to_string(protocol));
    35
    36      for (i = 0; i < n_fms; i++) {
    37          struct ofputil_flow_mod *fm = &fms[i];
    38          struct ofpbuf *msg;
    39
    40          msg = ofputil_encode_flow_mod(fm, protocol);
    41          ofpbuf_delete(msg);
    42
    43          free(CONST_CAST(struct ofpact *, fm->ofpacts));
    44          minimatch_destroy(&fm->match);
    45      }
    46  }
